  "temperature": 0,
  "messages": [
    {
      "role": "system",
      "content": "You are a role validation system. Your job is to determine whether the user's input is a real, recognizable job role. Return ONLY valid JSON with exactly these two fields: valid_role (boolean) and role (string). If the input is a valid job role, set valid_role to true and role to the normalized role name. If it is not a real job role, set valid_role to false and role to the best interpretation only when reasonably clear; otherwise use an empty string. Do not include markdown, explanations, code fences, or any other text."
    },
    {
      "role": "user",
      "content": "{{ $json.message.text }}"
    }
  ]
}

parameters.jsCode:
let data = $json;

if (typeof data.output === 'string') {
  try {
    data = JSON.parse(data.output);
  } catch (error) {
    throw new Error(`Could not parse agent output: ${data.output}`);
  }
} else if (data.output && typeof data.output === 'object') {
  data = data.output;
}

if (!data.role || typeof data.role !== 'string') {
  throw new Error(`Invalid agent output. Missing or invalid "role": ${JSON.stringify(data)}`);
}

if (!Array.isArray(data.companies) || data.companies.length === 0) {
  throw new Error(
    `Invalid agent output. Expected non-empty "companies" array but received: ${JSON.stringify(data)}`
  );
}

function formatNumber(n) {
  if (typeof n !== 'number') return 'N/A';
  return n.toLocaleString('en-IN');
}

function formatPeriod(period) {
  const periodMap = { yearly: 'year', annual: 'year', monthly: 'month', hourly: 'hour' };
  if (!period) return 'year';
  let p = period.toLowerCase().trim();
  p = p.replace(/^per\s+/, ''); // strip a leading "per " if the agent included it
  return periodMap[p] || p;
}

function salaryRow(level, tier) {
  if (!tier) return `| ${level} | N/A | N/A | N/A |`;
  return `| ${level} | ${formatNumber(tier.min)} | ${formatNumber(tier.max)} | ${tier.type || 'N/A'} |`;
}

let md = `# ${data.role} — Job Market Report\n\n`;
md += `_Generated on ${new Date().toLocaleDateString('en-IN', { year: 'numeric', month: 'long', day: 'numeric' })}_\n\n`;
md += `## Companies\n\n`;

for (const company of data.companies) {
  md += `### ${company.company || 'Unknown Company'}\n\n`;

  if (company.salary) {
    const currency = company.salary.currency || 'INR';
    const period = formatPeriod(company.salary.period);

    md += `**Salary (${currency} per ${period}):**\n\n`;
    md += `| Level | Min | Max | Type |\n`;
    md += `|---|---|---|---|\n`;
    md += `${salaryRow('Fresher', company.salary.fresher)}\n`;
    md += `${salaryRow('Mid', company.salary.mid)}\n`;
    md += `${salaryRow('Senior', company.salary.senior)}\n\n`;
  } else {
    md += `**Salary:** Not available\n\n`;
  }

  if (Array.isArray(company.skills) && company.skills.length > 0) {
    md += `**Skills:**\n\n`;
    for (const skill of company.skills) {
      md += `- ${skill}\n`;
    }
    md += `\n`;
  }

  md += `---\n\n`;
}

if (data.common_skills) {
  md += `## Common Skills Across Companies\n\n`;

  if (Array.isArray(data.common_skills.technical) && data.common_skills.technical.length > 0) {
    md += `### Technical Skills\n\n`;
    for (const skill of data.common_skills.technical) {
      md += `- ${skill}\n`;
    }
    md += `\n`;
  }

  if (Array.isArray(data.common_skills.non_technical) && data.common_skills.non_technical.length > 0) {
    md += `### Non-Technical Skills\n\n`;
    for (const skill of data.common_skills.non_technical) {
      md += `- ${skill}\n`;
    }
    md += `\n`;
  }
}

const fileName = `${(data.role || 'job_market_report').replace(/[^a-z0-9]+/gi, '_').toLowerCase()}_report.md`;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(md, 'utf8'),
  fileName,
  'text/markdown'
);

return [
  {
    json: { role: data.role },
    binary: { data: binaryData }
  }
];

